# Write your MySQL query statement below
select s.user_id, round(ifnull((select count(*) from Confirmations c where c.user_id=s.user_id and c.action='confirmed')/(select count(*) from Confirmations c where c.user_id=s.user_id),0),2) as confirmation_rate from Signups s left join Confirmations c on s.user_id=c.user_id group by s.user_id;